def parallel_source_files(original_sources, source_topic, frozen, hook):
    """Actual same-job source paths, including every restored original file."""
    result = []
    combined = dict(original_sources)
    combined.update(frozen)
    combined[HOOK_NAME] = sha(hook)
    combined[Path(__file__).name] = sha(__file__)
    prefix = "topics/visible-flexible-closed-surface/"
    payload_keys = {"input_config", "runtime_config", "frozen_ledger_ready", "frozen_stored_ready"}
    for name, expected in sorted(combined.items()):
        if name in payload_keys:
            continue
        if name.startswith(prefix):
            file = source_topic / name[len(prefix):]
        elif Path(name).name == name:
            file = HERE / name
        else:
            raise ValueError("Unmapped actual parallel source path: " + name)
        if not file.is_file() or sha(file) != expected:
            raise ValueError("Changed actual complete parallel source: " + name)
        result.append(dict(file=str(file.resolve()), bytes=file.stat().st_size, sha256=expected))
    return result

